21	import java.time.LocalDate;
22	import java.time.temporal.ChronoUnit;
23	
24	/**
25	 * Computes an owner's numeric membership level from its stored fields. The level starts at
26	 * {@link #BASE_LEVEL}, gains a point when the owner has an email and another when it has no
27	 * namesakes (a {@code namesakeCount} of 0) — capped at {@link #PRE_TENURE_MAX_LEVEL} before
28	 * tenure is considered — and gains a final point, up to {@link #MAX_LEVEL}, once the owner's
29	 * tenure exceeds {@link #TENURE_THRESHOLD_DAYS} days. A newly created owner has zero tenure,
30	 * so it never exceeds {@link #PRE_TENURE_MAX_LEVEL}.
31	 */
32	public abstract class MembershipLevelCalculator {
33	
34	    /** Level every owner starts at on creation. */
35	    public static final int BASE_LEVEL = 1;
36	
37	    /** Highest level awarded before tenure is taken into account; level 4 is reserved for tenure. */
38	    public static final int PRE_TENURE_MAX_LEVEL = 3;
39	
40	    /** Highest level this calculator awards, reached only by a sufficiently tenured owner. */
41	    public static final int MAX_LEVEL = 4;
42	
43	    /** Tenure, in days, that an owner must exceed to earn the tenure point (level 4). */
44	    public static final long TENURE_THRESHOLD_DAYS = 365;
45	
46	    /**
47	     * Return the membership level for the given owner: {@link #BASE_LEVEL}, plus one when an
48	     * email is present and one when {@code namesakeCount} is 0 (capped at
49	     * {@link #PRE_TENURE_MAX_LEVEL}), plus one when the owner's tenure exceeds
50	     * {@link #TENURE_THRESHOLD_DAYS} days, up to {@link #MAX_LEVEL}.
51	     */
52	    public static int levelOf(Owner owner) {
53	        int level = BASE_LEVEL;
54	        if (owner.hasEmail()) {
55	            level++;
56	        }
57	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
58	            level++;
59	        }
60	        level = Math.min(level, PRE_TENURE_MAX_LEVEL);
61	        if (hasQualifyingTenure(owner)) {
62	            level++;
63	        }
64	        return Math.min(level, MAX_LEVEL);
65	    }
66	
67	    /**
68	     * Whether the owner's tenure, measured from its registration date to today, exceeds
69	     * {@link #TENURE_THRESHOLD_DAYS} days. An owner with no registration date has no tenure.
70	     */
71	    private static boolean hasQualifyingTenure(Owner owner) {
72	        LocalDate registrationDate = owner.getRegistrationDate();
73	        if (registrationDate == null) {
74	            return false;
75	        }
76	        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > TENURE_THRESHOLD_DAYS;
77	    }
78	
79	}
